import { RendererCanvas, getCheckBox, getSlider } from '../../../lib'

import { BoidContollerWander0 } from './BoidContollerWander0';
import { BoidContollerWander1 } from './BoidContollerWander1';

export class Solution {
    public divHost: HTMLElement;
    public renderer: Renderer;
    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        // Center align
        // this.divHost.style.display = 'flex';
        // this.divHost.style.alignItems = 'center';

        const div = document.createElement('div');
        div.style.marginLeft = 'auto';
        div.style.marginRight = 'auto';
        div.style.backgroundColor = '#fff';
        div.style.width = '500px';
        div.style.height = '500px';
        this.divHost.appendChild(div);

        this.renderer = new Renderer(div);

        const text = document.createElement('div');
        div.append(text);
        text.textContent = 'Click or drag on canvas to populate agents'

        const ui = document.createElement('div');
        div.append(ui);

        const sl1 = getSlider('Delay', 1, 10);
        div.appendChild(sl1.div);
        sl1.slider.defaultValue = '3';
        sl1.slider.oninput = () => {
            this.renderer.BoidContoller.updateTargetDelay(+sl1.slider.value)
        };

        const sl2 = getSlider('Mass', 1, 500);
        div.appendChild(sl2.div);
        sl2.slider.defaultValue = '3';
        sl2.slider.oninput = () => {
            this.renderer.BoidContoller.updateMass(+sl2.slider.value)
        };

        const sl3 = getSlider('Velocity', 1, 10);
        div.appendChild(sl3.div);
        sl3.slider.defaultValue = '3';
        sl3.slider.oninput = () => {
            this.renderer.BoidContoller.updateVelocity(+sl3.slider.value)
        };

        const cBox = getCheckBox('target');
        ui.appendChild(cBox.div)
        cBox.checkBox.checked = false;
        cBox.checkBox.onchange = () => {
            // console.log(cBox.checkBox.checked)
            if (cBox.checkBox.checked === true) {
                this.renderer.toggleTargetRendering(true);
            } else {
                this.renderer.toggleTargetRendering(false);
            }
        }


    }
    public destroy() {
        this.renderer.destroy();
        while (this.divHost.lastElementChild) {
            this.divHost.removeChild(this.divHost.lastElementChild);
        }
    }
}

export class Renderer extends RendererCanvas {

    BoidContoller: BoidContollerWander0;
    dragTime = 0;

    constructor(div: any) {
        super(div);
        this.canvas.style.position = 'relative';
        this.canvas.style.width = '100%';
        this.canvas.style.height = '100%';

        // TODO
        // You code goes here for one time operation
        // 

        this.BoidContoller = new BoidContollerWander0();
        this.start();
    }
    public toggleTargetRendering(v: boolean) {
        this.BoidContoller.toggleTargetRendering(v);
    }
    public mouseDown(x: number, y: number): void {

    }
    public mouseUp(x: number, y: number): void {
        this.BoidContoller.AddAgent(x, y, this.canvas.width, this.canvas.height);
    }
    public mouseDrag(x: number, y: number): void {
        if (this.dragTime > 5) {
            this.BoidContoller.AddAgent(x, y, this.canvas.width, this.canvas.height);
            this.dragTime = 0;
        }
        this.dragTime++;
    }
    public render(ctx: CanvasRenderingContext2D): void {

        this.BoidContoller.Update();
        this.BoidContoller.Render(ctx);
    }
}